{
  "title": "The Crystal Caverns",
  "author": "Alaa",
  "difficulty": "easy",
  "sections": [
    {
      "sectionId": 1,
      "type": "BEGIN",
      "text": "You stand at the mouth of a crystal cave. What do you do?",
      "options": [
        {
          "description": "Follow the crystal tunnel",
          "gotoId": 2,
          "consequence": {
            "type": "HEALTH",
            "value": "0",
            "text": "You move carefully and keep your balance."
          }
        },
        {
          "description": "Examine the wall carvings",
          "gotoId": 3,
          "consequence": {
            "type": "GAIN_HEALTH",
            "value": "1",
            "text": "You find a glowing crystal shard."
          }
        }
      ]
    },
    {
      "sectionId": 2,
      "type": "NODE",
      "text": "The tunnel glows brighter ahead.",
      "options": [
        {
          "description": "Step through the lantern gate",
          "gotoId": 4,
          "consequence": {
            "type": "LOSE_HEALTH",
            "value": "-3",
            "text": "A crystal spike grazes your arm."
          }
        }
      ]
    },
    {
      "sectionId": 3,
      "type": "NODE",
      "text": "The carvings depict an ancient journey.",
      "options": [
        {
          "description": "Follow the symbol trail",
          "gotoId": 4,
          "consequence": {
            "type": "HEALTH",
            "value": "0",
            "text": "You feel wiser and steadier."
          }
        }
      ]
    },
    {
      "sectionId": 4,
      "type": "END",
      "text": "You emerge victorious from the cavern.",
      "options": []
    }
  ]
}
